class EditMarkerController(BaseController):

    def register_view(self, view):
        self.update_sensitivities()
        self.update_nanometer()

    def update_sensitivities(self):
        for name in ("style", "base", "align", "top", "color"):
            wid = self.view["marker_%s" % name]
            wid.set_sensitive(not getattr(self.model, "inherit_%s" % name)) 
        for name in ("angle", "top_offset"):
            self.view["spb_%s" % name].set_sensitive(not getattr(self.model, "inherit_%s" % name))

    # ------------------------------------------------------------
    #      Notifications of observable properties
    # ------------------------------------------------------------
    @Controller.observe("position", assign=True, after=True)
    def notif_parameter_changed(self, model, prop_name, info):
        if prop_name == "position":
            self.update_nanometer()

    @Controller.observe("inherit_style", assign=True)
    @Controller.observe("inherit_align", assign=True)
    @Controller.observe("inherit_base", assign=True)
    @Controller.observe("inherit_top", assign=True)
    @Controller.observe("inherit_top_offset", assign=True)
    @Controller.observe("inherit_angle", assign=True)
    @Controller.observe("inherit_color", assign=True)
    def notif_angle_toggled(self, model, prop_name, info):
        self.update_sensitivities()

    # ------------------------------------------------------------
    #      GTK Signal handlers
    # ------------------------------------------------------------
    def on_nanometer_changed(self, widget):
        try:
            position = float(widget.get_value())
        except ValueError:
            logger.exception("User set nanometers to an invalid value: %s", widget.get_value())
        else:
            self.model.set_nm_position(position)
        pass

    def update_nanometer(self):
        self.view["entry_nanometer"].set_value(self.model.get_nm_position())

    def on_sample_clicked(self, widget):

        def click_callback(x_pos, event):
            if self.edc is not None:
                self.edc.disconnect()
            self.view.get_toplevel().present()
            if x_pos != -1:
                self.model.position = x_pos

        self.edc = EyeDropper(
            self.parent.plot_controller,
            click_callback
        )

        self.view.get_toplevel().hide()
        self.parent.view.get_toplevel().present()

class MarkersController(ObjectListStoreController):
    """ 
        Controller for the markers list
    """

    file_filters = ("Marker file", get_case_insensitive_glob("*.MRK")),
    treemodel_property_name = "markers"
    treemodel_class_type = Marker
    columns = [
        (" ", "c_visible"),
        ("Marker label", "c_label")
    ]
    delete_msg = "Deleting a marker is irreversible!\nAre You sure you want to continue?"
    obj_type_map = [
        (Marker, EditMarkerView, EditMarkerController),
    ]
    title = "Edit Markers"

    def get_markers_tree_model(self, *args):
        return self.treemodel

    def setup_treeview_col_c_visible(self, treeview, name, col_descr, col_index, tv_col_nr):
        def toggle_renderer(column, cell, model, itr, data=None):
            try:
                col = column.get_col_attr("active")
                value = model.get_value(itr, col)
                cell.set_property('active', not_none(value, False))
            except TypeError:
                if settings.DEBUG: raise
                pass

        col = new_toggle_column(" ",
                toggled_callback=(self.on_marker_visible_toggled, (treeview.get_model(), col_index)),
                data_func=toggle_renderer,
                resizable=False,
                expand=False,
                activatable=True,
                active_col=col_index)
        setattr(col, "colnr", col_index)
        treeview.append_column(col)
        return True

    def select_markers(self, markers):
        self.set_selected_objects()

    @contextmanager
    def _multi_operation_context(self):
        with self.model.visuals_changed.hold():
            yield

    # ------------------------------------------------------------
    #      GTK Signal handlers
    # ------------------------------------------------------------
    def on_load_object_clicked(self, event):
        def on_accept(dialog):
            with self._multi_operation_context():
                for marker in Marker.get_from_csv(dialog.filename, self.model):
                    self.model.markers.append(marker)
        DialogFactory.get_load_dialog(
            "Import markers", parent=self.view.get_top_widget(),
            filters=self.file_filters
        ).run(on_accept)

    def on_save_object_clicked(self, event):
        def on_accept(dialog):
            Marker.save_as_csv(dialog.filename, self.get_selected_objects())
        DialogFactory.get_save_dialog(
            "Export markers", parent=self.view.get_top_widget(),
            filters=self.file_filters
        ).run(on_accept)

    def create_new_object_proxy(self):
        return Marker(label="New Marker", parent=self.model)

    def on_marker_visible_toggled(self, cell, path, model, colnr):
        if model is not None:
            itr = model.get_iter(path)
            model.set_value(itr, colnr, not cell.get_active())
            return True
        return False

    @BaseController.status_message("Finding peaks...", "find_peaks")
    def on_find_peaks_clicked(self, widget):
        btn = self.view['cmd_find_peaks']

        def re_enable():
            if btn is not None:
                btn.set_sensitive(True)

        def after_cb(threshold):
            # Freeze both windows while markers are inserted.
            # on_item_inserted is debounced (only the last insert schedules
            # a select_object idle at PRIORITY_DEFAULT_IDLE = 200); the
            # unfreeze runs at PRIORITY_LOW (300) so it fires after that
            # single deferred selection update.
            markers_window = self.view.get_top_widget()
            main_window = getattr(getattr(self, "parent", None), "view", None)
            main_window = main_window.get_top_widget() if main_window is not None else None
            for w in (markers_window, main_window):
                if w is not None:
                    w.set_sensitive(False)
            def re_enable_toplevel():
                for w in (markers_window, main_window):
                    if w is not None:
                        w.set_sensitive(True)
                re_enable()
                return GLib.SOURCE_REMOVE
            before = len(self.model.markers)
            self.model.auto_add_peaks(threshold)
            if len(self.model.markers) == before:
                re_enable_toplevel()
            else:
                GLib.idle_add(re_enable_toplevel, priority=GLib.PRIORITY_LOW)

        sel_model = ThresholdSelector(parent=self.model)
        sel_view = DetectPeaksView(parent=self.view)
        sel_ctrl = ThresholdController(model=sel_model, view=sel_view, parent=self, callback=after_cb, cancel_callback=re_enable) #@UnusedVariable

        def show_and_disable(*a, **k):
            if btn is not None:
                btn.set_sensitive(False)
            sel_view.present()

        show_threshold_plot = DialogFactory.get_progress_dialog(
            action=sel_model.update_threshold_plot_data,
            complete_callback=show_and_disable,
            gui_message="Finding peaks {progress:.0f}%...",
            toplevel=self.view.get_top_widget()
        )

        if len(self.model.markers) > 0:
            def on_accept(dialog):
                self.model.clear_markers()
                show_threshold_plot()
            def on_reject(dialog):
                show_threshold_plot()
            DialogFactory.get_confirmation_dialog(
                "Do you want to clear the current markers for this pattern?",
                parent=self.view.get_top_widget()
            ).run(on_accept, on_reject)
        else:
            show_threshold_plot()          

    def on_match_minerals_clicked(self, widget):
        # The dialog opens with the currently-selected marker as the sole target.
        # The user can append more targets inside the dialog (see MatchMineralController).
        initial_targets = self.get_selected_objects() or list(self.model.markers)
        all_markers = list(self.model.markers)

        def peak_of(marker):
            """Return (position in Angstrom, intensity) for a marker."""
            intensity = self.model.experimental_pattern.get_y_at_x(marker.position)
            return (marker.get_nm_position() * 10., intensity)

        def apply_cb(matches, targets):
            # Append every matched mineral's abbreviation to every marker in the
            # current target list (which the user may have grown in the dialog).
            with self._multi_operation_context():
                for name, abbreviation, peaks, inner, score in matches: #@UnusedVariable
                    if not abbreviation:
                        continue
                    for marker in targets:
                        existing = [x.strip() for x in marker.label.split(",")]
                        if abbreviation not in existing:
                            marker.label += ", %s" % abbreviation
                            marker.anno_label = ""  # clear so plotter falls back to label

        def close_cb():
            self.model.visuals_changed.emit()
            self.view.show()

        marker_peaks = [peak_of(m) for m in initial_targets]

        scorer_model = MineralScorer(marker_peaks=marker_peaks, parent=self.model)
        scorer_view = MatchMineralsView(parent=self.view)
        scorer_ctrl = MatchMineralController(
            model=scorer_model, view=scorer_view, parent=self,
            apply_callback=apply_cb, close_callback=close_cb,
            targets=list(initial_targets), all_markers=all_markers,
            peak_of=peak_of) #@UnusedVariable

        self.view.hide()
        scorer_view.present()

    pass # end of class

class MatchMineralController(DialogController):

    apply_callback = None
    close_callback = None

    # ------------------------------------------------------------
    #      Initialisation and other internals
    # ------------------------------------------------------------
    def __init__(self, model, view, spurious=False, auto_adapt=False, parent=None, apply_callback=None, close_callback=None, targets=None, all_markers=None, peak_of=None):
        DialogController.__init__(self, model=model, view=view, spurious=spurious, auto_adapt=auto_adapt, parent=parent)
        self.apply_callback = apply_callback
        self.close_callback = close_callback
        self.targets = list(targets) if targets else []
        self.all_markers = list(all_markers) if all_markers else []
        self.peak_of = peak_of
        # Built in register_view:
        self._targets_store = None
        self._tv_targets = None
        self._cmb_add = None
        self._available = []

    def register_adapters(self):
        super(MatchMineralController, self).register_adapters()
        if self.model is not None:
            self.reload_minerals()
            self.reload_matches()

    # ------------------------------------------------------------
    #      Targets panel
    # ------------------------------------------------------------
    def _build_targets_panel(self, box):
        """Build the target-peaks list + add/remove controls inside box_targets."""
        lbl = Gtk.Label(label="Target peaks:")
        lbl.set_xalign(0)
        box.pack_start(lbl, False, False, 0)

        self._targets_store = Gtk.ListStore(str, object)  # label, marker
        tv = Gtk.TreeView(model=self._targets_store)
        tv.set_headers_visible(False)
        tv.append_column(Gtk.TreeViewColumn("", Gtk.CellRendererText(), text=0))
        self._tv_targets = tv

        scw = Gtk.ScrolledWindow()
        scw.set_policy(Gtk.PolicyType.AUTOMATIC, Gtk.PolicyType.AUTOMATIC)
        scw.set_overlay_scrolling(False)
        scw.set_shadow_type(Gtk.ShadowType.IN)
        scw.set_size_request(180, 84)
        scw.add(tv)
        box.pack_start(scw, False, False, 0)

        btn_rm = Gtk.Button(label="Remove")
        btn_rm.connect("clicked", self.on_remove_target_clicked)
        box.pack_start(btn_rm, False, False, 0)

        box.pack_start(Gtk.Label(label="Add:"), False, False, 0)
        self._cmb_add = Gtk.ComboBoxText()
        box.pack_start(self._cmb_add, False, False, 0)

        btn_add = Gtk.Button(label="Add")
        btn_add.connect("clicked", self.on_add_target_clicked)
        box.pack_start(btn_add, False, False, 0)

        self._refresh_targets_ui()

    def _refresh_targets_ui(self):
        """Sync the targets list and the add-combo with self.targets."""
        if self._targets_store is None:
            return
        self._targets_store.clear()
        for m in self.targets:
            self._targets_store.append([m.label, m])

        self._available = [
            m for m in self.all_markers
            if not any(m is t for t in self.targets)
        ]
        self._cmb_add.remove_all()
        for m in self._available:
            self._cmb_add.append_text(m.label)
        if self._available:
            self._cmb_add.set_active(0)

    def _rebuild_and_rescore(self):
        """Rebuild marker_peaks from the current targets and re-run Auto Match."""
        if self.peak_of is not None:
            self.model.marker_peaks = [self.peak_of(m) for m in self.targets]
            self.model.auto_match()

    def on_add_target_clicked(self, widget):
        idx = self._cmb_add.get_active()
        if idx < 0 or idx >= len(self._available):
            return
        self.targets.append(self._available[idx])
        self._refresh_targets_ui()
        self._rebuild_and_rescore()   # automatic re-score on target change

    def on_remove_target_clicked(self, widget):
        sel = self._tv_targets.get_selection()
        model, itr = sel.get_selected()
        if itr is None:
            return
        if len(self.targets) <= 1:
            return   # keep at least one target
        marker = model.get_value(itr, 1)
        self.targets = [t for t in self.targets if t is not marker]
        self._refresh_targets_ui()
        self._rebuild_and_rescore()   # automatic re-score on target change

    def register_view(self, view):
        super(MatchMineralController, self).register_view(view)
        if view is not None:
            # Build the targets panel (target list + add/remove controls):
            box = view["box_targets"]
            if box is not None:
                self._build_targets_panel(box)
                box.show_all()
            # Explicitly connect buttons in case glade signal auto-wiring fails
            btn = view["btn_auto_match"]
            if btn is not None:
                btn.connect("clicked", self.on_auto_match_clicked)
            view['btn_apply'].set_sensitive(False)
            chk = view['chk_use_specimen_range']
            if chk is not None:
                chk.connect("toggled", self.on_use_specimen_range_toggled)
            # MATCHES Treeview:
            tv = self.view['tv_matches']

            setup_treeview(tv, None,
                reset=True,
                on_selection_changed=self.selection_changed,
                sel_mode='MULTIPLE',
            )

            tv.append_column(new_text_column(
                "Name", markup_col=0,
                xalign=0,
                expand=False,
                fixed_width=170,
            ))

            tv.append_column(new_text_column(
                "Abbr.", markup_col=1,
                expand=False,
                fixed_width=60,
            ))

            def get_value(column, cell, model, itr, *args):
                value = model.get_value(itr, column.get_col_attr('markup'))
                try: value = "%.5f" % value
                except TypeError: value = ""
                cell.set_property("markup", value)
                return
            tv.append_column(new_text_column(
                "Score",
                markup_col=4,
                expand=False,
                fixed_width=80,
                data_func=get_value
            ))

            # ALL MINERALS Treeview:
            tv = self.view['tv_minerals']
            setup_treeview(tv, None,
                reset=True,
                on_selection_changed=self.selection_changed,
            )

            tv.append_column(new_text_column(
                "Name", markup_col=0,
                xalign=0,
                expand=False,
                fixed_width=240,
            ))

            tv.append_column(new_text_column(
                "Abbr.", markup_col=1,
                expand=False,
                fixed_width=70,
            ))

    # ------------------------------------------------------------
    #      Notifications of observable properties
    # ------------------------------------------------------------
    @Controller.observe("matches_changed", signal=True)
    def notif_parameter_changed(self, model, prop_name, info):
        self.reload_matches()

    # ------------------------------------------------------------
    #      GTK Signal handlers
    # ------------------------------------------------------------
    def _filter_peaks_to_specimen_range(self, peaks):
        specimen = self.model.specimen
        x_data = specimen.experimental_pattern.data_x
        if x_data is None or x_data.size == 0:
            return peaks
        x_min, x_max = x_data.min(), x_data.max()
        filtered = []
        for position, intensity in peaks:
            two_theta = specimen.goniometer.get_2t_from_nm(position / 10.)
            if x_min <= two_theta <= x_max:
                filtered.append((position, intensity))
        return filtered

    def selection_changed(self, selection, *args):
        if selection.count_selected_rows() >= 1:
            model, paths = selection.get_selected_rows()
            itr = model.get_iter(paths[0])
            name, _, peaks = model.get(itr, 0, 1, 2)
            chk = self.view['chk_use_specimen_range']
            if chk is not None and chk.get_active():
                peaks = self._filter_peaks_to_specimen_range(peaks)
            self.model.specimen.mineral_preview = (name, peaks)
            self.model.specimen.visuals_changed.emit()
        tv_matches_sel = self.view.tv_matches.get_selection()
        self.view['btn_apply'].set_sensitive(tv_matches_sel.count_selected_rows() >= 1)

    def on_use_specimen_range_toggled(self, widget):
        for tv in (self.view.tv_matches, self.view.tv_minerals):
            sel = tv.get_selection()
            if sel.count_selected_rows() >= 1:
                self.selection_changed(sel)
                return

    def on_auto_match_clicked(self, event):
        self.model.auto_match()

    def on_add_match_clicked(self, event):
        selection = self.view.tv_minerals.get_selection()
        if selection.count_selected_rows() >= 1:
            model, paths = selection.get_selected_rows()
            itr = model.get_iter(paths[0])
            name, abbreviation, peaks = model.get(itr, 0, 1, 2)
            self.model.add_match(name, abbreviation, peaks)

    def on_del_match_clicked(self, event):
        selection = self.view.tv_matches.get_selection()
        if selection.count_selected_rows() >= 1:
            _, paths = selection.get_selected_rows()
            self.model.del_match(*paths[0])

    def on_apply_clicked(self, event):
        if self.apply_callback is not None and callable(self.apply_callback):
            self.model.specimen.mineral_preview = None
            selection = self.view.tv_matches.get_selection()
            tv_model, paths = selection.get_selected_rows()
            selected = [tv_model.get(tv_model.get_iter(p), 0, 1, 2, 3, 4) for p in paths]
            self.apply_callback(selected if selected else self.model.matches, list(self.targets))
        # Force a replot so the magenta preview sticks clear even when no
        # marker labels changed (e.g. a manually-added mineral with no overlap).
        self.model.specimen.visuals_changed.emit()
        self.view.hide()

    def on_cancel(self):
        if self.close_callback is not None and callable(self.close_callback):
            self.model.specimen.mineral_preview = None
            self.close_callback()
        self.view.hide()

    # ------------------------------------------------------------
    #      Methods & Functions
    # ------------------------------------------------------------
    def reload_matches(self):
        if not hasattr(self, 'tv_matches_model'):
            self.tv_matches_model = Gtk.ListStore(str, str, object, object, float)
        else:
            self.tv_matches_model.clear()
        for name, abbreviation, peaks, matches, score in self.model.matches:
            self.tv_matches_model.append([name, abbreviation, peaks, matches, score])

        tv = self.view.tv_matches
        tv.set_model(self.tv_matches_model)

        if self.model.matches:
            best_idx = max(range(len(self.model.matches)), key=lambda i: self.model.matches[i][4])
            path = Gtk.TreePath(best_idx)
            tv.get_selection().select_path(path)
            tv.scroll_to_cell(path, None, False, 0, 0)

    def reload_minerals(self):
        if not hasattr(self, 'tv_matches_model'):
            self.tv_minerals_model = Gtk.ListStore(str, str, object)
        else:
            self.tv_minerals_model.clear()
        for name, abbreviation, peaks in self.model.minerals:
            self.tv_minerals_model.append([name, abbreviation, peaks])

        tv = self.view.tv_minerals
        tv.set_model(self.tv_minerals_model)

    pass # end of class


class ThresholdController(DialogController):

    auto_adapt_included = [
        "pattern",
        "algorithm",
        "sel_threshold",
        "max_threshold",
        "sel_num_peaks",
        "steps",
        "min_distance",
    ]

    callback = None
    cancel_callback = None
    dline = None

    def __init__(self, *args, **kwargs):
        callback = kwargs.pop("callback", None)
        cancel_callback = kwargs.pop("cancel_callback", None)
        super(ThresholdController, self).__init__(*args, **kwargs)
        self.callback = callback
        self.cancel_callback = cancel_callback
        self.dline = None

    def _set_min_distance_visible(self, visible):
        """Show or hide the Min. distance row based on the selected algorithm."""
        for wid_id in ("lbl_min_distance", "min_distance"):
            wid = self.view[wid_id]
            if wid is not None:
                if visible:
                    wid.show()
                else:
                    wid.hide()

    def update_plot(self):
        if self.view is not None:
            self.view.plot.cla()
            if self.dline is not None:
                self.dline.disconnect()
                self.dline = None

            def dline_cb(x):
                self.model.sel_threshold = x

            if self.model is not None and self.model.threshold_plot_data is not None:
                x, y = self.model.threshold_plot_data
                self.view.plot.plot(x, y, 'k-')
                self.line = self.view.plot.axvline(x=self.model.sel_threshold, color="#0000FF", linestyle="-")
                self.dline = DraggableVLine(self.line, callback=dline_cb, window=self.view.matlib_canvas.get_window())
            self.view.plot.set_ylabel('# of peaks', labelpad=1)
            is_prominence = (getattr(self.model, 'algorithm', 'threshold') == 'prominence')
            xlabel = 'Min. prominence' if is_prominence else 'Threshold'
            self.view.plot.set_xlabel(xlabel, labelpad=1)
            self.view.figure.subplots_adjust(left=0.15, right=0.875, top=0.875, bottom=0.15)
            self.view.plot.autoscale_view()
            self.view.matlib_canvas.draw()

    def register_adapters(self):
        # Set initial visibility of min_distance row
        is_prominence = (getattr(self.model, 'algorithm', 'threshold') == 'prominence')
        self._set_min_distance_visible(is_prominence)
        self.update_plot()

    # ------------------------------------------------------------
    #      Notifications of observable properties
    # ------------------------------------------------------------
    @Controller.observe("algorithm", assign=True)
    def notif_algorithm_changed(self, model, prop_name, info):
        is_prominence = (model.algorithm == 'prominence')
        self._set_min_distance_visible(is_prominence)
        # Update the "Selected threshold/prominence" label in the dialog
        lbl = self.view['lbl_thold']
        if lbl is not None:
            lbl.set_text('Min. prominence:' if is_prominence else 'Selected threshold:')

    # ------------------------------------------------------------
    #      Notifications of observable properties
    # ------------------------------------------------------------
    @Controller.observe("sel_threshold", assign=True)
    @Controller.observe("threshold_plot_data", assign=True)
    def notif_parameter_changed(self, model, prop_name, info):
        self.update_plot()

    # ------------------------------------------------------------
    #      GTK Signal handlers
    # ------------------------------------------------------------
    def on_btn_ok_clicked(self, event):
        if self.callback is not None and callable(self.callback):
            self.callback(self.model)
        return DialogController.on_btn_ok_clicked(self, event)

    def on_cancel(self):
        if self.cancel_callback is not None and callable(self.cancel_callback):
            self.cancel_callback()
        return DialogController.on_cancel(self)

    pass # end of class
